namespace Muify.Service
{
    using System;
    using System.Text;
    using Microsoft.CodeAnalysis;
    using Microsoft.CodeAnalysis.Text;
    using MooVC.Syntax;
    using MooVC.Syntax.CSharp;
    using Attribute = System.Attribute;

    [Generator(LanguageNames.CSharp)]
    public sealed class NonMutationalGenerator
        : AttributeGenerator
    {
        /// <summary>
        /// The hint name used for the code generated by the generator.
        /// </summary>
        internal const string Hint = "NonMutationalAttribute.g.cs";

        /// <summary>
        /// The name of the attribute (without the suffix).
        /// </summary>
        internal const string Name = "NonMutational";

        /// <summary>
        /// The name of the type within the compilation that is used to determine whether the generator should run or not.
        /// </summary>
        internal const string Metadata = "Muify.Service.NonMutationalAttribute";

        public NonMutationalGenerator()
            : base(Hint, Metadata)
        {
        }

        protected override Snippet GetContent()
        {
            return Builder
                .New<Definition>()
                .From(typeof(NonMutationalGenerator))
                .For<Class>(@class => @class
                    .AttributedWith(attribute => attribute
                        .Named(typeof(AttributeUsageAttribute))
                        .WithArguments(
                            (Name: string.Empty, Value: "global::System.AttributeTargets.Class"),
                            (Name: nameof(AttributeUsageAttribute.AllowMultiple), Value: "false"),
                            (Name: nameof(AttributeUsageAttribute.Inherited), Value: "false")))
                    .DerivesFrom(typeof(Attribute))
                    .Named($"{Name}Attribute"))
                .ToSnippet(Configuration.Options);
        }
    }
}